-- QIB V2 isolated schema: run ONLY in a NEW dedicated QIB Supabase project.
begin;
create schema if not exists qib;
revoke all on schema qib from public, anon, authenticated;
create extension if not exists pgcrypto;
create table if not exists qib.centers(id uuid primary key default gen_random_uuid(), name text not null, branding jsonb not null default '{}', created_at timestamptz default now());
create table if not exists qib.specialties(id uuid primary key default gen_random_uuid(), code text unique not null, label text not null);
create table if not exists qib.memberships(user_id uuid not null, center_id uuid references qib.centers(id), role text not null check(role in ('nurse','supervisor','admin')), display_name text not null, primary key(user_id,center_id));
create table if not exists qib.assignments(user_id uuid not null, center_id uuid not null, specialty_id uuid references qib.specialties(id), primary key(user_id,center_id,specialty_id),foreign key(user_id,center_id) references qib.memberships(user_id,center_id));
create table if not exists qib.modules(id uuid primary key default gen_random_uuid(),center_id uuid references qib.centers(id),specialty_id uuid references qib.specialties(id),slug text not null,translations jsonb not null default '{}',status text not null default 'draft' check(status in ('draft','review','published','archived')),version integer not null default 1,updated_at timestamptz default now(),unique(center_id,slug));
create table if not exists qib.media(id uuid primary key default gen_random_uuid(),center_id uuid not null references qib.centers(id),module_id uuid references qib.modules(id),storage_path text not null,mime_type text not null,alt_text jsonb not null default '{}',status text not null default 'draft');
create table if not exists qib.assessments(id uuid primary key default gen_random_uuid(),center_id uuid not null references qib.centers(id),specialty_id uuid references qib.specialties(id),title text not null,status text not null default 'draft',starts_at timestamptz,ends_at timestamptz,minutes integer not null default 30 check(minutes between 1 and 240));
create table if not exists qib.questions(id uuid primary key default gen_random_uuid(),assessment_id uuid not null references qib.assessments(id),prompt_en text not null,options_en jsonb not null,answer_index integer not null check(answer_index>=0));
create table if not exists qib.attempts(id uuid primary key default gen_random_uuid(),assessment_id uuid not null references qib.assessments(id),center_id uuid not null references qib.centers(id),user_id uuid not null,status text not null default 'active' check(status in ('active','paused_review','submitted','void')),started_at timestamptz not null default now(),deadline_at timestamptz not null,heartbeat_at timestamptz not null default now(),answers jsonb not null default '{}',question_snapshot jsonb not null,score integer,finished_at timestamptz,unique(assessment_id,user_id));
create table if not exists qib.attempt_events(id uuid primary key default gen_random_uuid(),attempt_id uuid not null references qib.attempts(id),event_key text not null,kind text not null,actor_id uuid,reason text,occurred_at timestamptz not null default now(),unique(attempt_id,event_key));
create table if not exists qib.skill_definitions(id uuid primary key default gen_random_uuid(),specialty_id uuid references qib.specialties(id),name_en text not null,rubric jsonb not null default '{}');
create table if not exists qib.skill_observations(id uuid primary key default gen_random_uuid(),center_id uuid not null references qib.centers(id),user_id uuid not null,skill_id uuid references qib.skill_definitions(id),observer_id uuid not null,status text not null check(status in ('needs_support','supervised','competent')),notes text,observed_at timestamptz default now());
create table if not exists qib.learning_plans(id uuid primary key default gen_random_uuid(),center_id uuid not null references qib.centers(id),user_id uuid not null,specialty_id uuid references qib.specialties(id),steps jsonb not null default '[]',status text not null default 'active');
create table if not exists qib.content_revisions(id uuid primary key default gen_random_uuid(),module_id uuid references qib.modules(id),editor_id uuid not null,version integer not null,snapshot jsonb not null,created_at timestamptz default now());
create table if not exists qib.certificates(id uuid primary key default gen_random_uuid(),center_id uuid not null references qib.centers(id),user_id uuid not null,specialty_id uuid references qib.specialties(id),kind text not null check(kind in ('knowledge','competency')),issued_by uuid not null,issued_at timestamptz not null default now(),expires_at timestamptz,revoked_at timestamptz,evidence jsonb not null default '{}');
create table if not exists qib.notifications(id uuid primary key default gen_random_uuid(),center_id uuid references qib.centers(id),user_id uuid not null,kind text not null,body text not null,read_at timestamptz,created_at timestamptz default now());
-- No schema grants to anon/authenticated: access is ONLY through authenticated Render API.
-- RLS as defense in depth. Render DB credential is privileged: API MUST enforce tenant checks.
do $$ declare t text; begin for t in select tablename from pg_tables where schemaname='qib' loop execute format('alter table qib.%I enable row level security',t); end loop; end $$;
insert into qib.specialties(code,label) values('dental','Dental Nursing'),('dermatology','Dermatology Nursing') on conflict(code) do nothing;
commit;
